from pathlib import Path
import json
P=Path(__file__).parent;raw=(P/'plan.json').read_text();data=json.loads(raw)
canvas='''import {useState,useCanvasState,useHostTheme,H1,H2,Text,Grid,Stat} from 'cursor/canvas';
const D=DATA;
const positions=[0,1,2,3,5,6,7,8];
const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
export default function LunarMandala(){
 const t=useHostTheme(),[phase,setPhase]=useState<'current'|'future'>('current'),[selected,setSelected]=useState({pillar:0,action:0}),[done,setDone]=useCanvasState<Record<string,boolean>>('lunar-mandala-self-reported-v1',{}),[burn,setBurn]=useState(12000),[months,setMonths]=useState(3),[extra,setExtra]=useState(0),[receipts,setReceipts]=useState(0),[margin,setMargin]=useState(70);
 const plan=D[phase],g=plan.pillars[Math.max(0,selected.pillar)],action=selected.action>=0?g.actions[selected.action]:null,key=phase+'-'+selected.pillar+'-'+selected.action,gap=Math.max(0,burn*months+extra-receipts);
 const control={background:t.bg.elevated,color:t.text.primary,border:'1px solid '+t.stroke.primary,padding:8};
 function block(position:number){
  if(position===4)return <div key={position} style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:1,background:t.stroke.primary}}>{Array.from({length:9},(_,c)=>{const central=c===4,p=positions.indexOf(c);return <button key={c} onClick={()=>setSelected({pillar:central?-1:p,action:-1})} style={{padding:8,minHeight:88,border:0,background:central?t.accent.primary:t.fill.secondary,color:central?t.text.onAccent:t.text.primary,fontSize:central?13:12,fontWeight:600,cursor:'pointer'}}>{central?plan.title:plan.pillars[p].name}</button>})}</div>;
  const p=positions.indexOf(position),pillar=plan.pillars[p];
  return <div key={position} style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:1,background:t.stroke.primary}}>{Array.from({length:9},(_,c)=>{const center=c===4,a=positions.indexOf(c),item=center?null:pillar.actions[a],id=phase+'-'+p+'-'+a,active=selected.pillar===p&&selected.action===(center?-1:a);return <button key={c} title={center?pillar.goal:item!.how} aria-pressed={active} onClick={()=>setSelected({pillar:p,action:center?-1:a})} style={{minHeight:88,padding:7,border:0,background:active?t.fill.primary:center?t.fill.secondary:t.bg.editor,color:active?t.text.link:t.text.primary,fontSize:12,fontWeight:center?650:400,lineHeight:1.35,textAlign:'center',cursor:'pointer',textDecoration:!center&&done[id]?'line-through':'none'}}>{center?pillar.name:item!.title}</button>})}</div>;
 }
 return <main style={{padding:24,maxWidth:1400,margin:'auto',display:'grid',gap:24,fontFamily:'system-ui',background:t.bg.editor,color:t.text.primary}}>
 <header><H1>Lunar Paradox: current and future Mandala charts</H1><Text>18 October 2026 · Confirmed: $0 available cash, existing hardware and skills, no clients reported. Following is unmeasured. Every target is proposed; no task is marked complete by the author.</Text></header>
 <Grid columns="repeat(auto-fit,minmax(210px,1fr))" gap={18}><Stat label="Current combined baseline / month" value="$12,000"/><Stat label="Baseline-only 90-day gap" value="$36,000"/><Stat label="Proposed buyer conversations / 90 days" value="20–30"/><Stat label="Proposed paid pilots / 90 days" value="2"/></Grid>
 <section style={{background:t.fill.secondary,padding:16}}><Text><strong>Priority now:</strong> earn from one bounded service, deliver reliably and address the cash gap. No new paid agents, hiring, advertising or Labs purchases without funded need. The model did not establish a self-funding business at the current baseline.</Text></section>
 <nav aria-label="Planning horizon" style={{display:'flex',gap:12,flexWrap:'wrap'}}><button style={control} aria-pressed={phase==='current'} onClick={()=>{setPhase('current');setSelected({pillar:0,action:0})}}>Current: next 90 days</button><button style={control} aria-pressed={phase==='future'} onClick={()=>{setPhase('future');setSelected({pillar:0,action:0})}}>Future: evidence and funding gates</button></nav>
 <section><H2>{plan.title}</H2><Text>{plan.horizon}. The middle 3×3 names the eight priorities; each outer 3×3 expands one priority into eight actions. Select a cell for the how, evidence and timing.</Text></section>
 <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(300px,1fr))',gap:24,alignItems:'start'}}>
 <section style={{gridColumn:'1 / -1',overflowX:'auto'}}><div aria-label={phase+' Mandala chart'} style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:5,background:t.stroke.primary,padding:5,minWidth:770,maxWidth:1100,margin:'auto'}}>{Array.from({length:9},(_,i)=>block(i))}</div></section>
 <section style={{padding:18,border:'1px solid '+t.stroke.primary}}><Text>{g.name}</Text><H2>{selected.pillar<0?plan.title:action?action.title:g.goal}</H2>{selected.pillar<0?<><Text>{plan.horizon}</Text><ol>{plan.pillars.map(x=><li key={x.name}>{x.name}: {x.goal}</li>)}</ol></>:action?<><Text><strong>How:</strong> {action.how}</Text><Text><strong>Evidence:</strong> {action.proof}</Text><Text><strong>When:</strong> {action.when}</Text><Text><strong>Owner:</strong> {action.owner}</Text><label style={{display:'block',marginTop:16}}><input type="checkbox" checked={!!done[key]} onChange={e=>setDone({...done,[key]:e.target.checked})}/> Mark complete — self-reported, not independently verified</label></>:<ol>{g.actions.map((x,i)=><li key={i}><button onClick={()=>setSelected({pillar:selected.pillar,action:i})} style={{...control,background:'none',border:0,textAlign:'left'}}>{x.title}</button></li>)}</ol>}</section>
 <section style={{display:'grid',gap:12}}><H2>Funding requirement: adjustable cash illustration</H2><Text>Available cash is currently $0. These controls adjust a budget illustration, not a sales forecast or corporate tax calculation.</Text><label>Illustrative monthly baseline, USD <input type="number" min="0" value={burn} onChange={e=>setBurn(Math.max(0,Number(e.target.value)||0))} style={control}/></label><label>Baseline months <input type="number" min="1" max="12" value={months} onChange={e=>setMonths(Math.max(1,Math.min(12,Number(e.target.value)||1)))} style={control}/></label><label>Additional costs / provisions, USD <input type="number" min="0" value={extra} onChange={e=>setExtra(Math.max(0,Number(e.target.value)||0))} style={control}/></label><label>Actually available earned receipts, USD <input type="number" min="0" value={receipts} onChange={e=>setReceipts(Math.max(0,Number(e.target.value)||0))} style={control}/></label><Stat label="Illustrative uncovered cash requirement" value={money(gap)}/><Text>Additional costs default to zero because they are unknown, not because delivery or taxes are free. Exclude unearned or restricted funds from receipts.</Text><label>Illustrative contribution after delivery costs: {margin}% <input type="range" min="30" max="90" value={margin} onChange={e=>setMargin(Number(e.target.value))} style={{width:'100%',accentColor:t.accent.primary}}/></label><Text>Covering the illustrative {money(burn)} monthly baseline at that assumed contribution requires {money(burn/(margin/100))}/month in collected earned revenue, before taxes and additional reserves. Actual contribution is not verified.</Text></section>
 </div>
 <section><H2>Execution rhythm</H2><Text>First 7 days: bill ledger and cash deadlines; one buyer/problem/outcome; a real demo; ten researched prospects; specific conversations; costed scope; weekly review. Proposed 40-hour week: sales 14, delivery 16, administration/cash 4, useful content 4, supervision 2. Rebalance to actual obligations.</Text><Text>Future windows are conditional: repeatable Studio after successful paid deliveries; Products after repeated need and payment evidence; Labs after a bounded budget and committed permissible funding; hiring only after funded demand and adequate reserves for the new burn. No promised grant, investment valuation or follower count is assumed.</Text></section>
 </main>;
}
'''.replace('const D=DATA;','const D='+raw+';')
(P/'mandala.canvas.tsx').write_text(canvas)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lunar Paradox — Mandala plan</title><style>body{margin:0;background:#f6f6f3;color:#252823;font:15px/1.6 system-ui}main{max-width:1250px;margin:auto;padding:28px}h1{font-size:24px}h2{font-size:19px}button,input{font:inherit}button{cursor:pointer}.facts{display:flex;gap:30px;flex-wrap:wrap;margin:20px 0}.facts strong{display:block;font-size:20px}.note{background:#e8ebe3;padding:16px}.tabs{display:flex;gap:12px;margin:22px 0}.tabs button{padding:10px 15px;border:1px solid #b9bfb3;background:#fff}.tabs button[aria-pressed=true]{background:#344b34;color:#fff}.scroll{overflow:auto}.mandala{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;background:#555e50;padding:5px;min-width:790px}.block{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#b7bdb1}.cell{min-height:88px;padding:7px;border:0;background:#fff;color:#252823;font-size:12px;line-height:1.3}.center{font-weight:650;background:#e4e9dc}.goal{background:#344b34;color:#fff;font-weight:650}.cell[aria-pressed=true]{background:#edf1e7;outline:2px solid #344b34;outline-offset:-3px}.complete{text-decoration:line-through}.lower{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:28px;margin-top:24px}.detail{border:1px solid #b7bdb1;padding:18px}.budget label{display:block;margin:10px 0}.budget input[type=number]{padding:7px;width:130px}small{color:#555}a{color:#344b34}@media print{.tabs,.budget{display:none}.mandala{min-width:0}.cell{min-height:65px;font-size:10px}main{padding:5px}.lower{break-inside:avoid}}</style><main><h1>Lunar Paradox: current and future Mandala charts</h1><p>18 October 2026. Current cash: $0. Existing hardware and skills; no clients reported. Following is unmeasured. All targets are proposed, not achieved results.</p><div class="facts"><div>Monthly combined baseline<strong>$12,000</strong></div><div>Baseline-only 90-day gap<strong>$36,000</strong></div><div>Proposed buyer conversations / 90 days<strong>20–30</strong></div><div>Proposed paid pilots / 90 days<strong>2</strong></div></div><p class="note">Priority now: earn from one bounded service, deliver reliably and address the cash gap. No new paid agents, advertising, hires or Labs purchases without funded need. The simulation did not prove a self-funding business at the current baseline.</p><nav class="tabs" aria-label="Planning horizon"><button id="current">Current: next 90 days</button><button id="future">Future: evidence and funding gates</button></nav><h2 id="title"></h2><p id="horizon"></p><p>The central 3×3 names eight priorities. Each outer 3×3 expands one priority into eight actions. Select any action for how, evidence and timing. Scroll horizontally on narrow screens.</p><div class="scroll"><div class="mandala" id="chart"></div></div><div class="lower"><section class="detail" id="detail" aria-live="polite"></section><section class="budget"><h2>Uncovered cash: adjustable illustration</h2><p>Actual starting cash is $0. Enter costs and earned receipts; do not count restricted or unearned client money.</p><label>Illustrative monthly baseline, USD <input id="burn" type="number" min="0" value="12000"></label><label>Baseline months <input id="months" type="number" min="1" max="12" value="3"></label><label>Additional costs / provisions, USD <input id="extra" type="number" min="0" value="0"></label><label>Actually available earned receipts, USD <input id="receipts" type="number" min="0" value="0"></label><p>Illustrative cash requirement: <strong id="gap"></strong></p><small>Additional costs are unknown and default to zero; this does not mean delivery or taxes are free.</small><label>Illustrative contribution after delivery costs: <strong id="margin-label"></strong><input id="margin" type="range" min="30" max="90" value="70" style="width:100%"></label><p id="revenue"></p></section></div><h2>First seven days</h2><p>Map bills and deadlines; choose one buyer/problem/outcome; prepare a genuine demonstration; research ten suitable prospects; start specific conversations; cost the scope; review the evidence. No outreach is sent by this plan.</p><p>Proposed 40-hour week: 14 sales, 16 delivery, 4 administration/cash, 4 useful content, 2 supervision. Rebalance around real commitments. Choose three priority actions each week; do not attempt all 128 at once.</p><p>Completion marks are self-reported and local to this browser. They are not independently verified. Future dates are conditional; funding and delivery gates override the calendar.</p><a href="PLAN.md">Read the full written plan</a></main><script>const D=DATA;
const $=s=>document.getElementById(s),positions=[0,1,2,3,5,6,7,8],money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);let phase='current',selected={pillar:0,action:0},done={};try{done=JSON.parse(localStorage.getItem('lunar-mandala-self-report')||'{}')}catch{}
function chart(){const plan=D[phase];$('title').textContent=plan.title;$('horizon').textContent=plan.horizon;for(const k of ['current','future'])$(k).setAttribute('aria-pressed',String(k===phase));$('chart').innerHTML=Array.from({length:9},(_,b)=>`<div class="block">${Array.from({length:9},(_,c)=>{const hub=b===4,center=c===4,p=hub?(center?-1:positions.indexOf(c)):positions.indexOf(b),a=center?-1:positions.indexOf(c),g=plan.pillars[Math.max(0,p)],item=hub?null:center?null:g.actions[a],key=phase+'-'+p+'-'+a,active=!hub&&selected.pillar===p&&selected.action===a;return `<button class="cell ${hub&&center?'goal':hub||center?'center':''} ${!hub&&!center&&done[key]?'complete':''}" data-p="${p}" data-a="${hub?-1:a}" aria-pressed="${active}">${hub?(center?plan.title:g.name):center?g.name:item.title}</button>`}).join('')}</div>`).join('');detail();}
function detail(){if(selected.pillar<0){$('detail').innerHTML=`<h2>${D[phase].title}</h2><p>${D[phase].horizon}</p><ol>${D[phase].pillars.map(g=>`<li>${g.name}: ${g.goal}</li>`).join('')}</ol>`;return;}const g=D[phase].pillars[selected.pillar],a=selected.action>=0?g.actions[selected.action]:null,key=phase+'-'+selected.pillar+'-'+selected.action;$('detail').innerHTML=a?`<small>${g.name}</small><h2>${a.title}</h2><p><strong>How:</strong> ${a.how}</p><p><strong>Evidence:</strong> ${a.proof}</p><p><strong>When:</strong> ${a.when}</p><p><strong>Owner:</strong> ${a.owner}</p><label><input id="done" type="checkbox" ${done[key]?'checked':''}> Mark complete — self-reported</label>`:`<h2>${g.name}</h2><p>${g.goal}</p><ol>${g.actions.map(a=>`<li>${a.title}</li>`).join('')}</ol>`;if(a)$('done').onchange=e=>{done[key]=e.target.checked;try{localStorage.setItem('lunar-mandala-self-report',JSON.stringify(done))}catch{}chart();};}
$('chart').onclick=e=>{const b=e.target.closest('[data-p]');if(b){selected={pillar:Number(b.dataset.p),action:Number(b.dataset.a)};chart();}};for(const k of ['current','future'])$(k).onclick=()=>{phase=k;selected={pillar:0,action:0};chart();};
function budget(){const burn=Math.max(0,Number($('burn').value)||0),months=Math.max(1,Math.min(12,Number($('months').value)||1)),extra=Math.max(0,Number($('extra').value)||0),receipts=Math.max(0,Number($('receipts').value)||0),margin=Number($('margin').value);$('gap').textContent=money(Math.max(0,burn*months+extra-receipts));$('margin-label').textContent=margin+'%';$('revenue').textContent=`At that assumed contribution, covering the illustrative ${money(burn)} baseline requires ${money(burn/(margin/100))}/month collected earned revenue, before taxes and further reserves. Actual contribution is unverified.`;}for(const k of ['burn','months','extra','receipts','margin'])$(k).oninput=budget;chart();budget();
</script></html>'''.replace('const D=DATA;','const D='+raw+';')
(P/'index.html').write_text(html)
